import{_ as p,c as e,o as t,ah as r}from"./chunks/framework.Dnh4IO1K.js";const d=JSON.parse('{"title":"40、【解】 坎下震上","description":"周易阐真 - 40、【解】 坎下震上","frontmatter":{"title":"40、【解】 坎下震上","description":"周易阐真 - 40、【解】 坎下震上"},"headers":[],"relativePath":"zh/classics/chanzhen/041.md","filePath":"zh/classics/chanzhen/041.md"}'),s={name:"zh/classics/chanzhen/041.md"};function n(c,a,i,o,h,l){return t(),e("div",null,[...a[0]||(a[0]=[r('<blockquote><p>彖曰：解，险以动，动而免乎险，解。解，利西南，往得众也。其来复吉，乃得中也。有攸往夙吉，往有功也。天地解而雷雨作，雷雨作而百果草木皆甲坼。解之时大矣哉！</p></blockquote><h1 id="_40、【解】-坎下震上" tabindex="-1">40、【解】 坎下震上 <a class="header-anchor" href="#_40、【解】-坎下震上" aria-label="Permalink to “40、【解】 坎下震上”">​</a></h1><p>初六：无咎。</p><p>九二：田获三狐，得黄矢，贞吉。</p><p>六三：负且乘，致寇至。贞吝。</p><p>九四：解而拇，朋至斯孚。</p><p>六五：君子维有解，吉。有孚于小人。</p><p>上六：公用射隼于高墉之上，获之，无不利。</p><h2 id="孔易阐真-​" tabindex="-1">孔易阐真 ​ <a class="header-anchor" href="#孔易阐真-​" aria-label="Permalink to “孔易阐真 ​”">​</a></h2><p>大象：雷雨作，解。君子以赦过宥罪。</p><p>解者，脱散也。上震雷，下坎水，是雷动雨降，雷雨作而阴阳气通，解之象也。</p><p>君子有见于此，知修道者当阴气结滞之时，须用武火以煅炼；及阳气已复之时，宜用文火以温养。各有其时，不得差迟。以是于阴气解散以后，赦过宥罪，顺其自然，使其自消自化，而无容强制也。人之有过有罪者，皆由顺其后天，昧其先天，恣情纵欲，无所不至，此克制之功不可缺。克制者，改过消罪，以化气质耳。及其气质已化，先天来复，道心常存，人心不起，罪过已无，克制之功无所用矣。赦之者，赦其已往之过也；宥之者，宥其从前之罪也。赦之宥之，正气盛而邪气自无，真者在而假者不来。否则，不知止足，犹以罪过为念，终是人心用事，既无过而又招过，既无罪而又引罪，解而又不解，阴险尚在，阳气不纯，所谓“却除妄想重增病，趋向真如亦是差”者，是也。</p><h2 id="悟元子注解-​" tabindex="-1">悟元子注解 ​ <a class="header-anchor" href="#悟元子注解-​" aria-label="Permalink to “悟元子注解 ​”">​</a></h2><p>解，佳买反。夙，音宿。拇，茂后反。隼音信。</p><p>解者，脱散之义。卦德上震动，下坎险，阳气动而出险，险外之动，动之遂心，故谓解。此乘时采药之卦，承上睽卦而来。睽者，阴阳不和，悦明不当，阴气用事，阳气有陷，此解脱阳气之功不可缺。解脱阳气者，采药也。采药贵乎知时，若不知时，当面错过，阴气仍在，阳气又去，虽药在咫尺，未许我得。</p><p>悟真云：“铅遇癸生须急采，金逢望后不堪尝。”当其一阳生于坤地，先天之气，自虚无中来，天地之心回转，所谓西南得朋，正铅遇癸生，大药发现，道心震动，人心安静之时，此自然之解，吉之先见者也。是以解利西南，无所往，其来复，吉。无所往而来复，非人所勉强而然，乃一时自然之现露，出之于天。但天时已到，尤赖人力，急须下手扶阳抑阴，天人合发，借此一点阳气，复而又复，复于纯阳无阴之地，道心常存，人心永灭，方是解去危难，纵横逆顺，无不如意，是以有攸往夙吉也。</p><p>夙者，早也。早则药气方生，属于先天；迟则药气已过，属于后天。药气方生而急采，则先天坚固而得吉；药气已过而始采，则后天又发而不吉。夙吉二字，大有深意，有不得不早者，所谓“若到一阳才动处，便宜进火莫延迟”者是也。</p><p>初六，居于至险之地，柔弱无能，不能自出，而知亲近有道之士，借他人之智慧，以解自己之昏暗，有咎者亦能无咎。此柔而借刚解险者也。</p><p>九二，以一阳而居于二阴之内，刚而能柔，惟精惟一，允执厥中，既不使人心为恶，如田中获狐，而不纵放其狐，又不求人心强灭，如得黄矢，而不伤害其狐。不纵不伤，顺其所欲，渐次导之，使其自消自化，不解而解，解之而最吉者。此刚而用柔解险者也。</p><p>六三，愚而自用，妄想天宝，无道心而强制人心，以心制心，不但不能去人心，而且有以招人心。如负物者欲乘车，自致寇伤，虽解事属正，然恃一己之阴，不求他家之阳，亦修道者取吝之事。此柔而强欲解险者也。</p><p>九四，刚而不正，又应初阴，道心中人心相杂，解阴而不果，如解而拇矣。夫解散人心，所以振道心也。人心解去于道心来至，信之解之，在拇能动不能行，可见人心惟危，道心惟微矣。此刚为柔牵、不解险者也。</p><p>六五，虚人心而求道心，是君子维有解也。道心为君子之心，人心为小人之心。道心之解与未解，可于人心验之。人心化尽，方是道心之难解。若稍有一点人心，而道心之难犹未解去，故修道者必使宥密之中，而无丝毫滓质为极功。此点化群阴之解险者也。</p><p>上六，在解之终，一切客气尽消，只有人心未死，此一点人心，贪图无比，即罪之魁，如隼鸟栖于高墉，所当急须解去者。幸在解终，正气盛而邪气弱，以道心而解人心，直下断绝，无不利者。此大公无私之解险者也。</p><p>然则解难出险之道，贵于知时，尤贵于刚柔相当，不先不后，不急不缓，乘时下手，未有不获利者。然所以获利处，总要知的西南坤位耳。</p><p>噫!药出西南是坤位，欲寻坤位岂离人，分明说破君须记，只恐相逢认不真。西南坤位，岂易知哉!</p>',25)])])}const m=p(s,[["render",n]]);export{d as __pageData,m as default};
